package io.github.diodeme.ji.relay;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.nio.file.Path;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Base64;
import java.util.List;
import java.util.Optional;
import java.util.Set;

/** SQLite Relay metadata adapter with tenant-scoped queries and no business-payload column. */
public final class SqliteRelayMetadataStore implements RelayMetadataStore {
    private static final ObjectMapper MAPPER = new ObjectMapper();
    private final Connection connection;

    public SqliteRelayMetadataStore(Path database) {
        try {
            Path file = database.toAbsolutePath().normalize();
            java.nio.file.Files.createDirectories(file.getParent());
            connection = DriverManager.getConnection("jdbc:sqlite:" + file);
            connection.setAutoCommit(true);
            migrate();
        } catch (java.io.IOException | SQLException failure) {
            throw new IllegalStateException("Relay metadata store unavailable", failure);
        }
    }

    private void migrate() throws SQLException {
        try (var statement = connection.createStatement()) {
            statement.executeUpdate("PRAGMA journal_mode=WAL");
            statement.executeUpdate("CREATE TABLE IF NOT EXISTS relay_device (tenant_id TEXT NOT NULL, device_id TEXT NOT NULL, public_key BLOB NOT NULL, roles TEXT NOT NULL, created_at TEXT NOT NULL, revoked_at TEXT, PRIMARY KEY (tenant_id, device_id))");
            statement.executeUpdate("CREATE TABLE IF NOT EXISTS relay_host (tenant_id TEXT NOT NULL, host_id TEXT NOT NULL, public_key BLOB NOT NULL, protocol_version INTEGER NOT NULL, release_version TEXT NOT NULL, registered_at TEXT NOT NULL, PRIMARY KEY (tenant_id, host_id))");
            statement.executeUpdate("CREATE TABLE IF NOT EXISTS relay_invitation (tenant_id TEXT NOT NULL, invitation_id TEXT NOT NULL, issuer_device_id TEXT NOT NULL, host_ids TEXT NOT NULL, secret_hash BLOB NOT NULL, fingerprint TEXT NOT NULL, expires_at TEXT NOT NULL, confirmed_at TEXT, consumed_at TEXT, PRIMARY KEY (tenant_id, invitation_id))");
            statement.executeUpdate("CREATE TABLE IF NOT EXISTS relay_grant (tenant_id TEXT NOT NULL, host_id TEXT NOT NULL, device_id TEXT NOT NULL, requested_scopes TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (tenant_id, host_id, device_id))");
        }
    }

    @Override public synchronized Optional<Device> device(String tenantId, String deviceId) {
        try (PreparedStatement statement = connection.prepareStatement("SELECT public_key, roles, created_at, revoked_at FROM relay_device WHERE tenant_id=? AND device_id=?")) {
            statement.setString(1, tenantId); statement.setString(2, deviceId);
            try (ResultSet result = statement.executeQuery()) {
                if (!result.next()) return Optional.empty();
                return Optional.of(new Device(tenantId, deviceId, result.getBytes(1), relayRoles(result.getString(2)),
                        Instant.parse(result.getString(3)), optionalInstant(result.getString(4))));
            }
        } catch (SQLException failure) { throw unavailable(failure); }
    }

    @Override public synchronized List<Device> devices(String tenantId) {
        try (PreparedStatement statement = connection.prepareStatement("SELECT device_id, public_key, roles, created_at, revoked_at FROM relay_device WHERE tenant_id=? ORDER BY device_id")) {
            statement.setString(1, tenantId);
            var values = new ArrayList<Device>();
            try (ResultSet result = statement.executeQuery()) {
                while (result.next()) values.add(new Device(tenantId, result.getString(1), result.getBytes(2),
                        relayRoles(result.getString(3)), Instant.parse(result.getString(4)), optionalInstant(result.getString(5))));
            }
            return List.copyOf(values);
        } catch (SQLException failure) { throw unavailable(failure); }
    }

    @Override public synchronized void saveDevice(Device device) {
        device(device.tenantId(), device.deviceId()).ifPresent(existing -> {
            if (!java.security.MessageDigest.isEqual(existing.publicKey(), device.publicKey())) {
                throw new IllegalArgumentException("device identity changed");
            }
        });
        update("INSERT INTO relay_device(tenant_id,device_id,public_key,roles,created_at,revoked_at) VALUES(?,?,?,?,?,?) ON CONFLICT(tenant_id,device_id) DO UPDATE SET roles=excluded.roles,revoked_at=excluded.revoked_at",
                device.tenantId(), device.deviceId(), device.publicKey(), json(device.roles().stream().map(Enum::name).sorted().toList()),
                device.createdAt().toString(), device.revokedAt().map(Instant::toString).orElse(null));
    }

    @Override public synchronized void revokeDevice(String tenantId, String deviceId, Instant revokedAt) {
        update("UPDATE relay_device SET revoked_at=? WHERE tenant_id=? AND device_id=? AND revoked_at IS NULL",
                revokedAt.toString(), tenantId, deviceId);
    }

    @Override public synchronized Optional<Host> host(String tenantId, String hostId) {
        try (PreparedStatement statement = connection.prepareStatement("SELECT public_key,protocol_version,release_version,registered_at FROM relay_host WHERE tenant_id=? AND host_id=?")) {
            statement.setString(1, tenantId); statement.setString(2, hostId);
            try (ResultSet result = statement.executeQuery()) {
                return result.next() ? Optional.of(new Host(tenantId, hostId, result.getBytes(1), result.getInt(2),
                        result.getString(3), Instant.parse(result.getString(4)))) : Optional.empty();
            }
        } catch (SQLException failure) { throw unavailable(failure); }
    }

    @Override public synchronized void saveHost(Host host) {
        host(host.tenantId(), host.hostId()).ifPresent(existing -> {
            if (!java.security.MessageDigest.isEqual(existing.publicKey(), host.publicKey())) {
                throw new IllegalArgumentException("Host identity changed");
            }
        });
        update("INSERT INTO relay_host(tenant_id,host_id,public_key,protocol_version,release_version,registered_at) VALUES(?,?,?,?,?,?) ON CONFLICT(tenant_id,host_id) DO UPDATE SET protocol_version=excluded.protocol_version,release_version=excluded.release_version,registered_at=excluded.registered_at",
                host.tenantId(), host.hostId(), host.publicKey(), host.protocolVersion(), host.releaseVersion(), host.registeredAt().toString());
    }

    @Override public synchronized Optional<Invitation> invitation(String tenantId, String invitationId) {
        try (PreparedStatement statement = connection.prepareStatement("SELECT issuer_device_id,host_ids,secret_hash,fingerprint,expires_at,confirmed_at,consumed_at FROM relay_invitation WHERE tenant_id=? AND invitation_id=?")) {
            statement.setString(1, tenantId); statement.setString(2, invitationId);
            try (ResultSet result = statement.executeQuery()) {
                return result.next() ? Optional.of(new Invitation(tenantId, invitationId, result.getString(1),
                        strings(result.getString(2)), result.getBytes(3), result.getString(4), Instant.parse(result.getString(5)),
                        optionalInstant(result.getString(6)), optionalInstant(result.getString(7)))) : Optional.empty();
            }
        } catch (SQLException failure) { throw unavailable(failure); }
    }

    @Override public synchronized void saveInvitation(Invitation invitation) {
        update("INSERT INTO relay_invitation(tenant_id,invitation_id,issuer_device_id,host_ids,secret_hash,fingerprint,expires_at,confirmed_at,consumed_at) VALUES(?,?,?,?,?,?,?,?,?)",
                invitation.tenantId(), invitation.invitationId(), invitation.issuerDeviceId(), json(invitation.hostIds().stream().sorted().toList()),
                invitation.secretHash(), invitation.fingerprint(), invitation.expiresAt().toString(), null, null);
    }

    @Override public synchronized boolean confirmInvitation(String tenantId, String invitationId, String confirmingDeviceId, Instant confirmedAt) {
        return update("UPDATE relay_invitation SET confirmed_at=? WHERE tenant_id=? AND invitation_id=? AND issuer_device_id=? AND confirmed_at IS NULL AND consumed_at IS NULL AND expires_at>?",
                confirmedAt.toString(), tenantId, invitationId, confirmingDeviceId, confirmedAt.toString()) == 1;
    }

    @Override public synchronized boolean consumeInvitation(String tenantId, String invitationId, String deviceId, byte[] publicKey, Instant consumedAt) {
        return update("UPDATE relay_invitation SET consumed_at=? WHERE tenant_id=? AND invitation_id=? AND confirmed_at IS NOT NULL AND consumed_at IS NULL AND expires_at>?",
                consumedAt.toString(), tenantId, invitationId, consumedAt.toString()) == 1;
    }

    @Override public synchronized Optional<Grant> grant(String tenantId, String hostId, String deviceId) {
        try (PreparedStatement statement = connection.prepareStatement("SELECT requested_scopes,created_at FROM relay_grant WHERE tenant_id=? AND host_id=? AND device_id=?")) {
            statement.setString(1, tenantId); statement.setString(2, hostId); statement.setString(3, deviceId);
            try (ResultSet result = statement.executeQuery()) {
                return result.next() ? Optional.of(new Grant(tenantId, hostId, deviceId,
                        strings(result.getString(1)), Instant.parse(result.getString(2)))) : Optional.empty();
            }
        } catch (SQLException failure) { throw unavailable(failure); }
    }

    @Override public synchronized void saveGrant(Grant grant) {
        update("INSERT INTO relay_grant(tenant_id,host_id,device_id,requested_scopes,created_at) VALUES(?,?,?,?,?) ON CONFLICT(tenant_id,host_id,device_id) DO UPDATE SET requested_scopes=excluded.requested_scopes",
                grant.tenantId(), grant.hostId(), grant.deviceId(), json(grant.requestedScopes().stream().sorted().toList()), grant.createdAt().toString());
    }

    private int update(String sql, Object... values) {
        try (PreparedStatement statement = connection.prepareStatement(sql)) {
            for (int index = 0; index < values.length; index++) {
                Object value = values[index];
                if (value instanceof byte[] bytes) statement.setBytes(index + 1, bytes);
                else statement.setObject(index + 1, value);
            }
            return statement.executeUpdate();
        } catch (SQLException failure) { throw unavailable(failure); }
    }

    private static String json(Object value) {
        try { return MAPPER.writeValueAsString(value); }
        catch (com.fasterxml.jackson.core.JsonProcessingException failure) { throw new IllegalStateException(failure); }
    }
    private static Set<String> strings(String value) {
        try { return Set.copyOf(MAPPER.readValue(value, new TypeReference<List<String>>() {})); }
        catch (com.fasterxml.jackson.core.JsonProcessingException failure) { throw new IllegalStateException(failure); }
    }
    private static Set<RelayRole> relayRoles(String value) {
        return strings(value).stream().map(RelayRole::valueOf).collect(java.util.stream.Collectors.toUnmodifiableSet());
    }
    private static Optional<Instant> optionalInstant(String value) {
        return value == null ? Optional.empty() : Optional.of(Instant.parse(value));
    }
    private static IllegalStateException unavailable(SQLException failure) {
        return new IllegalStateException("Relay metadata store unavailable", failure);
    }

    @Override public synchronized void close() {
        try { connection.close(); } catch (SQLException failure) { throw unavailable(failure); }
    }
}
